const crypto = require("crypto")
const md5 = require("md5")

function useSecurity() {
  const INIT_VECTOR = "BSonK88FyMYQGSAi" // 16 bytes
  const KEY_VECTOR = "mZABZ7itIZjMG81reBgrywId90r0cBuO"

  const initVector = Buffer.from(INIT_VECTOR, "utf-8")
  const md5EncryptedKey = md5(KEY_VECTOR)
  const md5BufferKey = Buffer.from(md5EncryptedKey, "utf-8")

  const decrypt = (data) => {
    if (!data) return ""

    const cipher = crypto.createDecipheriv(
      "aes-256-cbc",
      md5BufferKey,
      initVector
    )

    return cipher.update(data, "base64", "utf-8") + cipher.final("utf-8")
  }

  return { decrypt }
}

// Example usage
const { decrypt } = useSecurity()

// Replace with real encrypted string
const encryptedText = ""
console.log(decrypt(encryptedText))
